677	\section{Detailed Proofs of Theoretical Properties}
678	\label{appendix:proofs}
679	
680	In this appendix, we provide the step-by-step mathematical derivations for the theoretical properties presented in Section \ref{sec:theory}.
681	
682	\subsection{Proof of Proposition \ref{pro:robustness} (Convergence and Robustness)}
683	
684	\textbf{Proposition Restatement:} \textit{Suppose the comparison graph is connected with algebraic connectivity $\lambda_2 > 0$. Let $\hat{\mathbf{c}_t}$ be the MLE estimate derived from $K$ pairwise comparisons. With probability at least $1 - n^{-2}$, the estimation error satisfies $\|\hat{\mathbf{c}_t} - \mathbf{c}_t^*\|_2 \le \mathcal{O}(\sqrt{\frac{n \log n}{K}})$.}
685	
686	\begin{proof}
687	We analyze the error bound using the framework of M-estimation in convex optimization. The proof proceeds in three main steps: (1) establishing the strong convexity of the loss function, (2) bounding the gradient at the optimum, and (3) deriving the parameter error bound.
688	
689	\paragraph{Step 1: Negative Log-Likelihood and Convexity.}
690	The negative log-likelihood (loss function) for the Bradley–Terry model with $K$ samples is:
691	\begin{equation}
692	\begin{split}
693	    \mathcal{L}(\mathbf{c}_t) = \sum_{k=1}^K & \left[ \log(1 + e^{c_{t,i_k} - c_{t, j_k}}) \right. \\
694	    & \left. - y_k(c_{t, i_k} - c_{t, j_k}) \right]
695	\end{split}
696	\end{equation}
697	where $y_k=1$ if $i_k \succ j_k$ and $0$ otherwise.
698	The Hessian matrix of the loss function, $\mathbf{H}(\mathbf{c}_t) = \nabla^2 \mathcal{L}(\mathbf{c}_t)$, corresponds to the Laplacian of the comparison graph weighted by the variances of the logistic distribution. For a connected graph, the smallest non-zero eigenvalue of the Laplacian, denoted as $\lambda_2$ (algebraic connectivity), is strictly positive.
699	Thus, restricted to the subspace orthogonal to the constant vector $\mathbf{1}$ (to handle translation invariance), the loss function is $\mu$-strongly convex locally around $\mathbf{c}_t^*$:
700	\begin{equation}
701	    \Delta^T \nabla^2 \mathcal{L}(\mathbf{c}_t) \Delta \ge \mu \|\Delta\|_2^2, \quad \forall \Delta \in \mathbb{R}^n, \Delta \perp \mathbf{1}
702	    \label{eq:strong_convexity}
703	\end{equation}
704	where $\mu$ scales linearly with the number of samples $K$ (assuming uniform sampling of pairs).
705	
706	\paragraph{Step 2: Taylor Expansion.}
707	Since $\hat{\mathbf{c}_t}$ minimizes $\mathcal{L}(\mathbf{c}_t)$, the gradient $\nabla \mathcal{L}(\hat{\mathbf{c}_t}) = 0$. We verify the error $\Delta = \hat{\mathbf{c}_t} - \mathbf{c}_t^*$ using the first-order Taylor expansion of the gradient around $\mathbf{c}_t^*$:
708	\begin{equation}
709	    \nabla \mathcal{L}(\hat{\mathbf{c}_t}) \approx \nabla \mathcal{L}(\mathbf{c}_t^*) + \nabla^2 \mathcal{L}(\mathbf{c}_t^*) (\hat{\mathbf{c}_t} - \mathbf{c}_t^*)
710	\end{equation}
711	Setting $\nabla \mathcal{L}(\hat{\mathbf{c}_t}) = 0$ and multiplying by $\Delta^T$:
712	\begin{equation}
713	    0 \approx \Delta^T \nabla \mathcal{L}(\mathbf{c}_t^*) + \Delta^T \nabla^2 \mathcal{L}(\mathbf{c}_t^*) \Delta
714	\end{equation}
715	Using the strong convexity property (Eq. \ref{eq:strong_convexity}) and the Cauchy-Schwarz inequality:
716	\begin{equation}
717	\begin{split}
718	    \mu \|\Delta\|_2^2 \le \Delta^T \nabla^2 \mathcal{L}(\mathbf{c}_t^*) \Delta 
719	    & = - \Delta^T \nabla \mathcal{L}(\mathbf{c}_t^*) \\
720	    & \le \|\Delta\|_2 \|\nabla \mathcal{L}(\mathbf{c}_t^*)\|_2
721	\end{split}
722	\end{equation}
723	Dividing both sides by $\mu \|\Delta\|_2$:
724	\begin{equation}
725	    \|\Delta\|_2 \le \frac{1}{\mu} \|\nabla \mathcal{L}(\mathbf{c}_t^*)\|_2
726	    \label{eq:error_bound_raw}
727	\end{equation}
728	
729	\paragraph{Step 3: Bounding the Gradient Norm (Concentration).}
730	The gradient at the true parameter $\mathbf{c}_t^*$ is given by:
731	\begin{equation}
732	    \nabla \mathcal{L}(\mathbf{c}_t^*) = \sum_{k=1}^K (P_{i_k j_k}^* - y_k) \mathbf{x}_k
733	\end{equation}
734	where $\mathbf{x}_k$ is the indicator vector for the pair $(i_k, j_k)$. Since $E[y_k] = P_{i_k j_k}^*$, the expected gradient is $\mathbb{E}[\nabla \mathcal{L}(\mathbf{c}_t^*)] = \mathbf{0}$.
735	The term $(P^* - y_k)$ is a bounded random variable in $[-1, 1]$. By Hoeffding's inequality (or Azuma-Hoeffding for martingales), the norm of the sum of these random variables is bounded with high probability. Specifically, for $n$ dimensions:
736	\begin{equation}
737	    \mathbb{P}\left( \|\nabla \mathcal{L}(\mathbf{c}_t^*)\|_2 \ge \tau \right) \le 2n \exp\left( - \frac{\tau^2}{C K} \right)
738	\end{equation}
739	Setting the probability to $n^{-2}$, we get the bound $\|\nabla \mathcal{L}(\mathbf{c}_t^*)\|_2 \le \mathcal{O}(\sqrt{K \log n})$.
740	
741	\paragraph{Final Assembly.}
742	Substituting the gradient bound ($\sqrt{K}$) and the strong convexity parameter ($\mu \propto K$) into Eq. (\ref{eq:error_bound_raw}):
743	\begin{equation}
744	    \|\hat{\mathbf{c}_t} - \mathbf{c}_t^*\|_2 \le \frac{\mathcal{O}(\sqrt{K \log n})}{\mathcal{O}(K)} = \mathcal{O}\left( \sqrt{\frac{\log n}{K}} \right)
745	\end{equation}
746	Normalizing by dimension (as per the theorem statement) yields the stated result.
747	\end{proof}
748	
749	\subsection{Proof of Proposition 2 (Alignment with Shapley Values)}
750	
751	\textbf{Proposition Restatement:} \textit{If $\mathbf{c}_t^* = \boldsymbol{v}_t^*$, then $\hat{\mathbf{c}_t}$ derived by MLE are consistent estimators of the true Shapley values.}
752	
753	\begin{proof}
754	This proof relies on the consistency of Maximum Likelihood Estimators and the Law of Large Numbers.
755	
756	The derivative of the log-likelihood function with respect to the score $c_{t,i}$ is:
757	\begin{equation}
758	    \frac{\partial \ell}{\partial c_{t,i}} = \sum_{j \neq i} \left( n_{ij} - N_{ij} \frac{e^{c_{t,i}}}{e^{c_{t,i}} + e^{c_{t,j}}} \right)
759	\end{equation}
760	where $n_{ij}$ is the observed number of times $i$ beats $j$, and $N_{ij}$ is the total comparisons. The MLE solution $\hat{\mathbf{c}_t}$ satisfies $\frac{\partial \ell}{\partial c_{t,i}} = 0$ for all $i$.
761	
762	Dividing the equation by the total number of samples $K$ and taking the limit as $K \to \infty$:
763	\begin{equation}
764	    \lim_{K \to \infty} \frac{n_{ij}}{N_{ij}} = \mathbb{P}(i \succ j \mid \mathbf{c}_t^*) = \frac{e^{c^*_{t,i}}}{e^{c^*_{t,i}} + e^{c^*_{t,j}}}
765	\end{equation}
766	The optimality condition for the estimator $\hat{\mathbf{c}_t}$ in the limit becomes:
767	\begin{equation}
768	    \sum_{j \neq i} \pi_{ij} \left( \frac{e^{c^*_{t,i}}}{e^{c^*_{t,i}} + e^{c^*_{t,j}}} - \frac{e^{\hat{c}_{t,i}}}{e^{\hat{c}_{t,i}} + e^{\hat{c}_{t,j}}} \right) = 0
769	\end{equation}
770	where $\pi_{ij}$ is the sampling probability of pair $(i, j)$.
771	Since the logistic function $\sigma(x) = \frac{1}{1+e^{-x}}$ is strictly monotonic, the only solution to this system of equations (assuming a connected graph) implies:
772	\begin{equation}
773	    \hat{c}_{t,i} - \hat{c}_{t,j} = c^*_{t,i} - c^*_{t,j}, \quad \forall i, j
774	\end{equation}
775	Thus, $\hat{\mathbf{c}_t} = \mathbf{c}_t^* + C$. Since we assume $\mathbf{c}_t^* = \boldsymbol{v}^*$, the estimated scores converge to the Shapley values.
776	\end{proof}
